package com.protractor.backend.domain.dm.repository;
import com.protractor.backend.domain.dm.entity.DmMessage; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface DmMessageRepository extends JpaRepository<DmMessage,Long>{ Page<DmMessage> findByDmRoomIdOrderByCreatedAtDescIdDesc(Long roomId, Pageable pageable); Optional<DmMessage> findFirstByDmRoomIdOrderByCreatedAtDescIdDesc(Long roomId); boolean existsByDmRoomIdAndSenderMemberIdNotAndReadAtIsNull(Long roomId,Long sender); long countByDmRoomIdAndSenderMemberIdNotAndReadAtIsNull(Long roomId,Long sender); @Modifying @Query("update DmMessage m set m.readAt = CURRENT_TIMESTAMP where m.dmRoomId=:roomId and m.senderMemberId<>:memberId and m.readAt is null") int markUnreadReceivedAsRead(@Param("roomId") Long roomId,@Param("memberId") Long memberId); }
